import AuthRouter from "@/model/authentication/route.js";
import academicSessionRouter from "@/model/academic-session/session/academic-session.route.js";
import termRouter from "@/model/academic-session/term/term.route.js";
import classLevelRouter from "@/model/class/level/class.route.js";
import teacherAvailabilityRouter from "@/model/teacher/availability.route.js";
import teacherRouter from "@/model/teacher/teacher.route.js";
import subjectRouter from "@/model/subject/subject.route.js";
import roomRouter from "@/model/room/room.route.js";
import periodRouter from "@/model/period/period.route.js";
import periodScheduleRouter from "@/model/period/Schedule/schedule.route.js";
import schoolRouter from "@/model/school/school.route.js";
import express from "express";
import { subjectAssignmentRoute } from "@/model/assignment/subject/subject.assignment.route.js";
import { teachingAssignmentRouter } from "@/model/assignment/teacher/teachingAssignment.route.js";
import { teacherSubjectRouter } from "@/model/assignment/teacher-subject/teacher-subject.route.js";
import timetableRouter from "@/model/timetable/timetable.route.js";
import timetableEntryRouter from "@/model/timetable/entry/timetable-entry.route.js";
const router = express.Router();
router.get("/health", (req, res) => {
    res.status(200).json({ status: "ok" });
});
router.use("/auth", AuthRouter);
router.use("/academic-sessions", academicSessionRouter);
router.use("/academic-sessions/:sessionId/terms", termRouter);
router.use("/class-levels", classLevelRouter);
router.use("/teachers/:teacherId/availability", teacherAvailabilityRouter);
router.use("/teachers", teacherRouter);
router.use("/subjects", subjectRouter);
router.use("/rooms", roomRouter);
router.use("/periods", periodRouter);
router.use("/period-schedules", periodScheduleRouter);
router.use("/schools", schoolRouter);
router.use("/assignments/subjects", subjectAssignmentRoute);
router.use("/assignments/teaching", teachingAssignmentRouter);
router.use("/assignments/teacher-subjects", teacherSubjectRouter);
router.use("/timetables", timetableRouter);
router.use("/timetables", timetableEntryRouter);
export default router;
